:root{--p3:url(data:image/jpeg;base64,);--p4:url(data:image/jpeg;base64,);--p5:url(data:image/jpeg;base64,);--p6:url(data:image/jpeg;base64,);--p7:url(data:image/jpeg;base64,);--p1:url(data:image/jpeg;base64,);--p2:url(data:image/jpeg;base64,);--brand:#8c5731;--brand-l:#d4a47b;--bg:#14100d;--bg2:#1b1511;--card:#221a14;--line:#34281f;--text:#ede4da;--mute:#ae9f90;--font:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
*{box-sizing:border-box;margin:0}
html{background-color:#14100d;color:#ede4da;scroll-behavior:smooth;scroll-padding-top:72px}
body{background-color:#14100d;color:#ede4da;font-family:var(--font);font-size:1.02rem;line-height:1.65}
a{color:var(--brand-l)}
:focus-visible{outline:2px solid var(--brand-l);outline-offset:3px}
h1,h2,h3{line-height:1.15;letter-spacing:-.02em;font-weight:650}
h2{font-size:clamp(1.8rem,3.6vw,2.6rem);margin-bottom:.6rem}
h3{font-size:1.2rem;margin-bottom:.4rem}
.wrap{max-width:1100px;margin:0 auto;padding:0 1.5rem}
section{padding:5.5rem 0}
section{background:radial-gradient(ellipse 70% 60% at 100% 100%,rgba(140,87,49,.2),transparent 70%),var(--bg)}
.alt{background:radial-gradient(ellipse 70% 60% at 0% 0%,rgba(140,87,49,.26),transparent 70%),var(--bg2)}
.lead{color:var(--mute);max-width:58ch;margin-bottom:2.2rem}
.btn{display:inline-block;font:600 1rem var(--font);background:var(--brand);color:#fff;border:1px solid var(--brand);padding:.8rem 1.5rem;border-radius:10px;text-decoration:none;cursor:pointer;transition:background .3s ease,transform .3s ease}
.btn:hover{background:#a1663a;transform:translateY(-2px)}
.btn.ghost{background:transparent;color:var(--text);border-color:var(--line)}
.btn.ghost:hover{background:var(--card);border-color:var(--brand-l)}

nav{position:sticky;top:0;z-index:20;background:rgba(20,16,13,.92);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem;height:64px}
.logo{font-weight:700;letter-spacing:.18em;color:var(--text);text-decoration:none}
nav ul{display:flex;gap:1.4rem;list-style:none;padding:0;font-size:.92rem}
nav ul a{color:var(--mute);text-decoration:none;transition:color .3s}
nav ul a:hover{color:var(--text)}
.burger{display:none;background:none;border:1px solid var(--line);color:var(--text);font:inherit;padding:.35rem .8rem;border-radius:8px;cursor:pointer}

.hero{padding:6rem 0 5rem;background:radial-gradient(ellipse at 85% 10%,rgba(140,87,49,.38),transparent 55%),radial-gradient(ellipse at 5% 100%,rgba(140,87,49,.2),transparent 50%),var(--bg)}
.hero .wrap{display:grid;grid-template-columns:1.3fr .7fr;gap:3rem;align-items:center}
.hero h1{font-size:clamp(2.4rem,6vw,4.4rem);margin-bottom:1.2rem}
.hero p{color:var(--mute);max-width:52ch;margin-bottom:1.8rem}
.hero .btn+.btn{margin-left:.5rem}
.in{opacity:0;transform:translateY(18px);animation:in .8s ease forwards}
.in:nth-child(2){animation-delay:.15s}.in:nth-child(3){animation-delay:.3s}.in:nth-child(4){animation-delay:.45s}
@keyframes in{to{opacity:1;transform:none}}
.badge{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:1.6rem;transition:border-color .3s,transform .3s}
.badge:hover{border-color:var(--brand);transform:translateY(-4px)}
.badge b{font-size:2.6rem;letter-spacing:-.03em;color:var(--brand-l)}
.badge p{margin:.2rem 0 0;font-size:.95rem}
.badge hr{border:0;border-top:1px solid var(--line);margin:1rem 0}

.r{opacity:0;transform:translateY(22px);transition:opacity .8s ease,transform .8s ease}
.r.v{opacity:1;transform:none}

.grid{display:grid;gap:1.2rem;grid-template-columns:repeat(auto-fit,minmax(250px,1fr))}
.card{background:linear-gradient(160deg,#2f2218,var(--card) 60%);border:1px solid var(--line);border-radius:14px;padding:1.6rem;height:100%;transition:transform .35s ease,border-color .35s ease,box-shadow .35s ease}
.card:hover{transform:translateY(-6px);border-color:var(--brand);box-shadow:0 14px 30px rgba(0,0,0,.4)}
.card p{color:var(--mute);font-size:.98rem}
.ico{width:42px;height:42px;border-radius:10px;background:var(--brand);display:grid;place-items:center;margin-bottom:1rem}
.ico svg{width:22px;height:22px;stroke:#fff;fill:none;stroke-width:1.7}

.about{display:grid;grid-template-columns:1.1fr .9fr;gap:3rem;align-items:center}
.about p+p{margin-top:1rem;color:var(--mute)}
.facts{display:grid;gap:.8rem}
.facts div{display:flex;justify-content:space-between;gap:1rem;padding:.9rem 1.1rem;background:var(--card);border:1px solid var(--line);border-radius:12px;transition:border-color .3s}
.facts div:hover{border-color:var(--brand)}
.facts span{color:var(--mute)}.facts b{color:var(--brand-l);font-weight:600;text-align:right}

.ph{background-size:cover;background-position:center}
.ph1{background-image:var(--p1)}.ph2{background-image:var(--p2)}.ph3{background-image:var(--p3);background-position:center 50%}.ph4{background-image:var(--p4)}.ph5{background-image:var(--p5);background-position:center 40%}.ph6{background-image:var(--p6);background-position:center 65%}.ph7{background-image:var(--p7);background-position:center 60%}
.gal{display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:170px;gap:.9rem}
.gal figure{position:relative;overflow:hidden;border-radius:14px;display:flex;align-items:flex-end;border:1px solid var(--line);transition:transform .4s ease,filter .4s ease}
.gal figure:hover{transform:scale(1.02);filter:brightness(1.15)}
.gal figcaption{position:relative;z-index:1;padding:.9rem;font-size:.92rem;color:#fff;text-shadow:0 1px 6px rgba(0,0,0,.7)}
.gal .ph::after{content:"";position:absolute;inset:auto 0 0 0;height:55%;background:linear-gradient(transparent,rgba(0,0,0,.65))}
.gal .w{grid-column:span 2}.gal .tall{grid-row:span 2}
.t1{background:repeating-linear-gradient(45deg,#3a2616 0 10px,#2d1c10 10px 20px)}
.t2{background:linear-gradient(135deg,#8c5731,#2a1a0e)}
.t3{background:radial-gradient(circle at 70% 40%,#7d4f2b,#1f150d 70%)}
.t4{background:repeating-radial-gradient(circle at 30% 70%,#382410 0 12px,#2b1b0f 12px 24px)}
.t5{background:linear-gradient(160deg,#5a3a20,#1a110b)}
.hp{height:170px;border-radius:10px;margin-bottom:1.1rem}
.chips{display:flex;flex-wrap:wrap;gap:.6rem;margin-top:2rem}
.chips span{padding:.5rem 1rem;border:1px solid var(--brand);border-radius:999px;color:var(--brand-l);background:rgba(140,87,49,.12);transition:background .3s,color .3s}
.chips span:hover{background:var(--brand);color:#fff}
.split{display:grid;grid-template-columns:1fr 1fr;gap:3rem;align-items:center}
.split+.split{margin-top:3.5rem}
.split h2{font-size:clamp(1.6rem,3vw,2.2rem)}
.split p{color:var(--mute);margin-bottom:1.3rem;max-width:48ch}
.pbox{aspect-ratio:4/3;border-radius:16px;border:1px solid var(--line);box-shadow:0 18px 40px rgba(0,0,0,.45);transition:transform .5s ease}
.pbox:hover{transform:scale(1.02)}
.split.rev .pbox{order:2}
.band{background:linear-gradient(180deg,#1b1511 0%,#2f1f13 15%,#5a3820 33%,#8c5731 50%,#5a3820 67%,#2a1b10 85%,#14100d 100%);background-color:#8c5731;color:#fff;padding:3.2rem 0;text-align:center}
.band p{font-size:clamp(1.15rem,2.4vw,1.6rem);max-width:36ch;margin:0 auto;font-weight:600;line-height:1.3;letter-spacing:-.01em}
.band small{display:block;margin-top:.5rem;opacity:.9;font-size:.9rem}

blockquote p{color:var(--text);font-size:1rem}
blockquote footer{margin-top:1rem;font-size:.88rem;color:var(--brand-l)}

.price{font-size:1.9rem;letter-spacing:-.02em;color:var(--brand-l);margin:.3rem 0 .6rem;font-weight:650}
.card.hl{border-color:var(--brand);background:linear-gradient(180deg,#2e2016,var(--card))}
.note{margin-top:1.2rem;font-size:.85rem;color:var(--mute)}
.tag{font-size:.85rem;color:var(--brand-l)}

details{border-bottom:1px solid var(--line);padding:1rem 0;max-width:760px}
summary{cursor:pointer;list-style:none;font-size:1.1rem;font-weight:550;display:flex;justify-content:space-between;gap:1rem}
summary::-webkit-details-marker{display:none}
summary::after{content:"+";color:var(--brand-l);font-size:1.4rem;line-height:1;transition:transform .3s}
details[open] summary::after{transform:rotate(45deg)}
details p{color:var(--mute);margin-top:.6rem}

.contact{display:grid;grid-template-columns:.9fr 1.1fr;gap:3rem}
.info p{margin-bottom:1rem;color:var(--mute)}.info strong{display:block;color:var(--text);font-weight:600}
form{display:grid;gap:1rem}
label{display:grid;gap:.3rem;font-size:.9rem;color:var(--mute)}
input,select,textarea{font:1rem var(--font);background-color:#0f0b09;color:var(--text);border:1px solid var(--line);border-radius:10px;padding:.75rem;width:100%;transition:border-color .3s}
input:focus,select:focus,textarea:focus{border-color:var(--brand-l);outline:none}
.row{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
#ok{display:none;padding:1rem;border:1px solid var(--brand);background:rgba(140,87,49,.2);border-radius:10px;font-size:.95rem}
footer.main{background:radial-gradient(ellipse 60% 120% at 50% 100%,rgba(140,87,49,.28),transparent 70%),var(--bg);padding:2rem 0;border-top:1px solid var(--line);text-align:center;font-size:.9rem;color:var(--mute)}

[hidden]{display:none!important}
nav ul a.navbtn{background:var(--brand);color:#fff;padding:.4rem 1rem;border-radius:10px;transition:background .3s}
nav ul a.navbtn:hover{background:#a1663a}
.back{display:inline-block;margin-bottom:1.5rem;font-size:.95rem;text-decoration:none}
.back:hover{text-decoration:underline}
.resh{padding-top:4rem;min-height:80vh}
.resh h1{font-size:clamp(2rem,5vw,3.2rem);margin-bottom:.6rem}
.cta{text-align:center;background:radial-gradient(ellipse 80% 90% at 50% 120%,rgba(140,87,49,.5),transparent 70%),var(--bg)}.cta .lead{margin-left:auto;margin-right:auto}.cta .btn+.btn{margin-left:.5rem}
.facts3{margin-top:3rem}
.glow{position:relative;height:0;z-index:1}
.glow::before{content:"";position:absolute;left:0;right:0;top:-55px;height:110px;pointer-events:none;background:radial-gradient(ellipse 45% 50% at 50% 50%,rgba(140,87,49,.4) 0%,rgba(140,87,49,.2) 40%,rgba(140,87,49,.07) 70%,transparent 100%)}
@media(max-width:860px){
.hero .wrap,.about,.contact{grid-template-columns:1fr}
.gal{grid-template-columns:1fr 1fr}.gal .tall{grid-row:auto}.split{grid-template-columns:1fr}.split.rev .pbox{order:0}
.burger{display:block}
nav ul{display:none;position:absolute;top:64px;left:0;right:0;flex-direction:column;background:var(--bg);padding:1rem 1.5rem;border-bottom:1px solid var(--line)}
nav ul.open{display:flex}
section{padding:4rem 0}.row{grid-template-columns:1fr}
}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}.r,.in{opacity:1;transform:none}}
